// SIM-024: `%p`/`%0p` of unpacked arrays (ascending, descending and
// multidimensional), records with native members, nesting, enums, packed
// structures and unions, X/Z elements and containers (SV 21.2.1.7).
module tb;
  typedef enum logic [1:0] {RED, GREEN, BLUE} color_e;
  typedef struct packed { logic [3:0] hi; logic [3:0] lo; } nib_t;
  typedef union packed { logic [7:0] raw; nib_t n; } bytes_u;
  typedef struct { int x; string s; real r; } rec_t;
  typedef struct { rec_t inner; int arr [2]; color_e c; } nest_t;
  typedef struct { int q [$]; string tag; } qrec_t;
  typedef struct packed { color_e c; nib_t n; logic signed [3:0] s; } pk_t;
  typedef struct { pk_t p; logic [1:0][3:0] pa; } hold_t;
  int a [3];
  int rv [2:0];
  logic [3:0] m [0:1][2:0];
  string sa [2];
  real ra [-1:0];
  color_e col, bad;
  nib_t nb;
  bytes_u bu;
  rec_t rc;
  nest_t ns;
  qrec_t qr;
  logic [3:0] xa [2];
  int q [$];
  int empty_q [$];
  string sq [$];
  int d [];
  int ai [int];
  int aempty [int];
  string as [string];
  rec_t rq [$];
  int qq [$][$];
  int t [$];
  pk_t pks [2];
  hold_t hd;
  initial begin
    a = '{1, 2, 3};
    rv = '{7, 8, 9};
    foreach (m[i, j]) m[i][j] = 4'(i * 3 + j);
    sa = '{"x", "y\"z"};
    ra = '{1.5, -0.25};
    col = BLUE;
    bad = color_e'(3);
    nb = '{4'h1, 4'h2};
    bu.raw = 8'h34;
    rc = '{5, "str", 1.5};
    ns.inner = rc;
    ns.arr = '{3, 4};
    ns.c = GREEN;
    qr.q = '{1, 2};
    qr.tag = "t";
    xa[0] = 4'bx01z;
    q = '{10, 20, 30};
    sq = '{"a", ""};
    d = new[2];
    d[0] = -1;
    d[1] = 2;
    ai[5] = 50;
    ai[-3] = 30;
    as["k1"] = "v1";
    as["k0"] = "v0";
    rq.push_back(rc);
    rc.x = 6;
    rc.s = "";
    rc.r = 0.5;
    rq.push_back(rc);
    t.push_back(1);
    qq.push_back(t);
    t.delete();
    qq.push_back(t);
    t.push_back(2);
    t.push_back(3);
    qq.push_back(t);
    $display("A|%p|%0p|", a, a);
    $display("B|%p|", rv);
    $display("C|%p|", m);
    $display("D|%p|%p|", sa, ra);
    $display("E|%p|%p|%0p|%d|", col, bad, col, col);
    $display("F|%p|%0p|%p|", nb, nb, bu);
    $display("G|%p|", rq[0]);
    $display("H|%0p|", rc);
    $display("I|%p|", ns);
    $display("J|%p|", qr);
    $display("K|%p|", xa);
    $display("L|%p|%0p|%p|%p|", q, q, empty_q, sq);
    $display("M|%p|%p|%p|%p|", d, ai, aempty, as);
    $display("N|%p|", rq);
    $display("O|%p|%0p|", qq, qq);
    $display("P|%s|", $sformatf("%p", a));
    $display("Q|%0d|%0d|%p|", q.size(), ai.num(), a);
    pks[0] = '{GREEN, '{4'h3, 4'hc}, -4'sd2};
    pks[1] = '{RED, '{4'h0, 4'h1}, 4'sd7};
    hd.p = pks[0];
    hd.pa = 8'h21;
    $display("R|%p|", pks);
    $display("S|%p|%0p|", hd, hd);
    $display("T|%p|%p|", pks[1], hd.pa);
    $finish(0);
  end
endmodule
